import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_f32_t16x16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    // Register declarations
    .reg .pred %p0, %p1, %pW1, %pW2, %pW;
    .reg .pred %pTx8, %pTx4, %pRowOk, %pAStart, %pAEnd, %pAall;
    .reg .pred %pBrowOk0, %pBrowOk1, %pBcolEndOk0, %pBcolEndOk1, %pBAll0, %pBAll1;
    .reg .pred %pAj0, %pAj1, %pAj2, %pAj3, %pBj0, %pBj1, %pBj2, %pBj3;
    .reg .b32 %rTx, %rTy, %rBx, %rBy, %rBdx, %rBdy;
    .reg .b32 %rRow, %rCol, %r0, %r1, %r2, %rN;
    .reg .b32 %rTileCount, %rTile, %rKtile;
    .reg .b32 %rAcolV, %rAcolEnd, %rBcolV, %rBcolEnd, %rColBase;
    .reg .b32 %rSoffAV, %rSoffBV0, %rSoffBV1, %rTmp32, %rJ, %rK;
    .reg .b64 %rdA, %rdB, %rdC;
    .reg .b64 %rdAsBase, %rdBsBase;
    .reg .b64 %rd2, %rd3, %rd4, %rd5, %rd6, %rd7, %rd8, %rdTmp, %rdArowPtr, %rdBcolPtr, %rdIncA, %rdIncB;
    .reg .f32 %fAcc, %fA2, %fB2;
    .reg .f32 %fA4_0, %fA4_1, %fA4_2, %fA4_3, %fB4_0, %fB4_1, %fB4_2, %fB4_3;
    .shared .align 16 .b8 Asub[2048]; // 16*32*4
    .shared .align 16 .b8 Bsub[2048]; // 32*16*4
    // Load parameters
    ld.param.u64 %rdA, [A_ptr];
    ld.param.u64 %rdB, [B_ptr];
    ld.param.u64 %rdC, [C_ptr];
    ld.param.u32 %rN, [N];
    // Thread and block indices
    mov.u32 %rTx, %tid.x;
    mov.u32 %rTy, %tid.y;
    mov.u32 %rBx, %ctaid.x;
    mov.u32 %rBy, %ctaid.y;
    mov.u32 %rBdx, %ntid.x;
    mov.u32 %rBdy, %ntid.y;
    // Compute global row and column indices
    mul.lo.u32 %r0, %rBy, %rBdy;
    add.u32 %rRow, %r0, %rTy;
    mul.lo.u32 %r1, %rBx, %rBdx;
    add.u32 %rCol, %r1, %rTx;
    mov.u32 %rColBase, %r1; // block column base
    // Initialize accumulator
    mov.f32 %fAcc, 0f00000000;
    // Number of tiles along K: (N + 31) >> 5
    add.u32 %r2, %rN, 31;
    shr.u32 %rTileCount, %r2, 5;
    // Shared memory base addresses
    mov.u64 %rdAsBase, Asub;
    mov.u64 %rdBsBase, Bsub;
    mov.u32 %rTile, 0;
TilesLoop:
    setp.ge.u32 %p0, %rTile, %rTileCount;
    @%p0 bra TilesEnd;
    // Ktile = tile * 32
    shl.b32 %rKtile, %rTile, 5;
    // Predicates for vector participation
    setp.lt.u32 %pTx8, %rTx, 8;   // A loads: 8 threads per row x 4 = 32 elements
    setp.lt.u32 %pTx4, %rTx, 4;   // B loads: 4 threads per row x 4 = 16 elements
    // --------------------
    // Vectorized load A tile (16x32) with fallback for boundaries
    // a_col_vec = Ktile + 4*tx
    shl.b32 %rAcolV, %rTx, 2;
    add.u32 %rAcolV, %rAcolV, %rKtile;
    add.u32 %rAcolEnd, %rAcolV, 3;
    // smem offset for Asub[ty][4*tx]
    mul.lo.u32 %rSoffAV, %rTy, 32;
    shl.b32 %rTmp32, %rTx, 2;
    add.u32 %rSoffAV, %rSoffAV, %rTmp32;
    // Check row and col bounds
    setp.lt.u32 %pRowOk, %rRow, %rN;
    setp.lt.u32 %pAStart, %rAcolV, %rN;
    setp.lt.u32 %pAEnd, %rAcolEnd, %rN;
    and.pred %pAall, %pRowOk, %pAStart;
    and.pred %pAall, %pAall, %pAEnd;
    @!%pTx8 bra SkipALoad;
    // Compute shared address for A
    cvt.u64.u32 %rdTmp, %rSoffAV;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rd3, %rdAsBase, %rdTmp;
    @%pAall bra ALoadVecOK;
    // Fallback: per-element guarded scalar loads for A
    mov.f32 %fA4_0, 0f00000000;
    mov.f32 %fA4_1, 0f00000000;
    mov.f32 %fA4_2, 0f00000000;
    mov.f32 %fA4_3, 0f00000000;
    // j = 0
    mov.u32 %rJ, %rAcolV;
    setp.lt.u32 %pAj0, %rJ, %rN;
    and.pred %pAj0, %pAj0, %pRowOk;
    @!%pAj0 bra ANoLoad0;
    mul.wide.u32 %rd2, %rRow, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd2, %rd2, %rdTmp;
    shl.b64 %rd2, %rd2, 2;
    add.u64 %rd2, %rd2, %rdA;
    ld.global.f32 %fA4_0, [%rd2];
ANoLoad0:
    // j = 1
    add.u32 %rJ, %rAcolV, 1;
    setp.lt.u32 %pAj1, %rJ, %rN;
    and.pred %pAj1, %pAj1, %pRowOk;
    @!%pAj1 bra ANoLoad1;
    mul.wide.u32 %rd2, %rRow, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd2, %rd2, %rdTmp;
    shl.b64 %rd2, %rd2, 2;
    add.u64 %rd2, %rd2, %rdA;
    ld.global.f32 %fA4_1, [%rd2];
ANoLoad1:
    // j = 2
    add.u32 %rJ, %rAcolV, 2;
    setp.lt.u32 %pAj2, %rJ, %rN;
    and.pred %pAj2, %pAj2, %pRowOk;
    @!%pAj2 bra ANoLoad2;
    mul.wide.u32 %rd2, %rRow, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd2, %rd2, %rdTmp;
    shl.b64 %rd2, %rd2, 2;
    add.u64 %rd2, %rd2, %rdA;
    ld.global.f32 %fA4_2, [%rd2];
ANoLoad2:
    // j = 3
    add.u32 %rJ, %rAcolV, 3;
    setp.lt.u32 %pAj3, %rJ, %rN;
    and.pred %pAj3, %pAj3, %pRowOk;
    @!%pAj3 bra ANoLoad3;
    mul.wide.u32 %rd2, %rRow, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd2, %rd2, %rdTmp;
    shl.b64 %rd2, %rd2, 2;
    add.u64 %rd2, %rd2, %rdA;
    ld.global.f32 %fA4_3, [%rd2];
ANoLoad3:
    st.shared.v4.f32 [%rd3], {%fA4_0, %fA4_1, %fA4_2, %fA4_3};
    bra ALoadDone;
ALoadVecOK:
    // Vectorized load & store for A
    mul.wide.u32 %rd2, %rRow, %rN;
    cvt.u64.u32 %rdTmp, %rAcolV;
    add.u64 %rd2, %rd2, %rdTmp;
    shl.b64 %rd2, %rd2, 2;
    add.u64 %rd2, %rd2, %rdA;
    ld.global.v4.f32 {%fA4_0, %fA4_1, %fA4_2, %fA4_3}, [%rd2];
    st.shared.v4.f32 [%rd3], {%fA4_0, %fA4_1, %fA4_2, %fA4_3};
ALoadDone:
SkipALoad:
    // --------------------
    // Vectorized load B tile (32x16) in two 16-row halves, with fallback
    // First 16 rows: k_row0 = Ktile + ty
    add.u32 %rTmp32, %rKtile, %rTy;        // rTmp32 = k_row0
    // col vector start and end
    shl.b32 %rBcolV, %rTx, 2;               // 4*tx
    add.u32 %rBcolV, %rBcolV, %rColBase;    // block col base + 4*tx
    add.u32 %rBcolEnd, %rBcolV, 3;
    // smem offset for Bsub[k_row0][4*tx]
    mul.lo.u32 %rSoffBV0, %rTy, 16;
    shl.b32 %rJ, %rTx, 2;
    add.u32 %rSoffBV0, %rSoffBV0, %rJ;
    // predicates
    setp.lt.u32 %pBrowOk0, %rTmp32, %rN;
    setp.lt.u32 %pBcolEndOk0, %rBcolEnd, %rN;
    and.pred %pBAll0, %pBrowOk0, %pBcolEndOk0;
    @!%pTx4 bra SkipBLoad0;
    // shared address
    cvt.u64.u32 %rdTmp, %rSoffBV0;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rd5, %rdBsBase, %rdTmp;
    @%pBAll0 bra BLoad0VecOK;
    // Fallback scalar for first 16 rows
    mov.f32 %fB4_0, 0f00000000;
    mov.f32 %fB4_1, 0f00000000;
    mov.f32 %fB4_2, 0f00000000;
    mov.f32 %fB4_3, 0f00000000;
    // j = 0
    mov.u32 %rJ, %rBcolV;
    setp.lt.u32 %pBj0, %rJ, %rN;
    and.pred %pBj0, %pBj0, %pBrowOk0;
    @!%pBj0 bra BNoLoad00;
    mul.wide.u32 %rd4, %rTmp32, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd4, %rd4, %rdTmp;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rdB;
    ld.global.f32 %fB4_0, [%rd4];
BNoLoad00:
    // j = 1
    add.u32 %rJ, %rBcolV, 1;
    setp.lt.u32 %pBj1, %rJ, %rN;
    and.pred %pBj1, %pBj1, %pBrowOk0;
    @!%pBj1 bra BNoLoad01;
    mul.wide.u32 %rd4, %rTmp32, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd4, %rd4, %rdTmp;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rdB;
    ld.global.f32 %fB4_1, [%rd4];
BNoLoad01:
    // j = 2
    add.u32 %rJ, %rBcolV, 2;
    setp.lt.u32 %pBj2, %rJ, %rN;
    and.pred %pBj2, %pBj2, %pBrowOk0;
    @!%pBj2 bra BNoLoad02;
    mul.wide.u32 %rd4, %rTmp32, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd4, %rd4, %rdTmp;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rdB;
    ld.global.f32 %fB4_2, [%rd4];
BNoLoad02:
    // j = 3
    add.u32 %rJ, %rBcolV, 3;
    setp.lt.u32 %pBj3, %rJ, %rN;
    and.pred %pBj3, %pBj3, %pBrowOk0;
    @!%pBj3 bra BNoLoad03;
    mul.wide.u32 %rd4, %rTmp32, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd4, %rd4, %rdTmp;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rdB;
    ld.global.f32 %fB4_3, [%rd4];
BNoLoad03:
    st.shared.v4.f32 [%rd5], {%fB4_0, %fB4_1, %fB4_2, %fB4_3};
    bra BLoad0Done;
BLoad0VecOK:
    mul.wide.u32 %rd4, %rTmp32, %rN;
    cvt.u64.u32 %rdTmp, %rBcolV;
    add.u64 %rd4, %rd4, %rdTmp;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rdB;
    ld.global.v4.f32 {%fB4_0, %fB4_1, %fB4_2, %fB4_3}, [%rd4];
    st.shared.v4.f32 [%rd5], {%fB4_0, %fB4_1, %fB4_2, %fB4_3};
BLoad0Done:
SkipBLoad0:
    // Second 16 rows: k_row1 = k_row0 + 16
    add.u32 %rTmp32, %rTmp32, 16;          // rTmp32 = k_row1
    // smem offset for Bsub[k_row1][4*tx] -> add 256 elements
    add.u32 %rSoffBV1, %rSoffBV0, 256;
    // predicates
    setp.lt.u32 %pBrowOk1, %rTmp32, %rN;
    setp.lt.u32 %pBcolEndOk1, %rBcolEnd, %rN;
    and.pred %pBAll1, %pBrowOk1, %pBcolEndOk1;
    @!%pTx4 bra SkipBLoad1;
    // shared address for second half
    cvt.u64.u32 %rdTmp, %rSoffBV1;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rd5, %rdBsBase, %rdTmp;
    @%pBAll1 bra BLoad1VecOK;
    // Fallback scalar for second 16 rows
    mov.f32 %fB4_0, 0f00000000;
    mov.f32 %fB4_1, 0f00000000;
    mov.f32 %fB4_2, 0f00000000;
    mov.f32 %fB4_3, 0f00000000;
    // j = 0
    mov.u32 %rJ, %rBcolV;
    setp.lt.u32 %pBj0, %rJ, %rN;
    and.pred %pBj0, %pBj0, %pBrowOk1;
    @!%pBj0 bra BNoLoad10;
    mul.wide.u32 %rd4, %rTmp32, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd4, %rd4, %rdTmp;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rdB;
    ld.global.f32 %fB4_0, [%rd4];
BNoLoad10:
    // j = 1
    add.u32 %rJ, %rBcolV, 1;
    setp.lt.u32 %pBj1, %rJ, %rN;
    and.pred %pBj1, %pBj1, %pBrowOk1;
    @!%pBj1 bra BNoLoad11;
    mul.wide.u32 %rd4, %rTmp32, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd4, %rd4, %rdTmp;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rdB;
    ld.global.f32 %fB4_1, [%rd4];
BNoLoad11:
    // j = 2
    add.u32 %rJ, %rBcolV, 2;
    setp.lt.u32 %pBj2, %rJ, %rN;
    and.pred %pBj2, %pBj2, %pBrowOk1;
    @!%pBj2 bra BNoLoad12;
    mul.wide.u32 %rd4, %rTmp32, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd4, %rd4, %rdTmp;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rdB;
    ld.global.f32 %fB4_2, [%rd4];
BNoLoad12:
    // j = 3
    add.u32 %rJ, %rBcolV, 3;
    setp.lt.u32 %pBj3, %rJ, %rN;
    and.pred %pBj3, %pBj3, %pBrowOk1;
    @!%pBj3 bra BNoLoad13;
    mul.wide.u32 %rd4, %rTmp32, %rN;
    cvt.u64.u32 %rdTmp, %rJ;
    add.u64 %rd4, %rd4, %rdTmp;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rdB;
    ld.global.f32 %fB4_3, [%rd4];
BNoLoad13:
    st.shared.v4.f32 [%rd5], {%fB4_0, %fB4_1, %fB4_2, %fB4_3};
    bra BLoad1Done;
BLoad1VecOK:
    mul.wide.u32 %rd4, %rTmp32, %rN;
    cvt.u64.u32 %rdTmp, %rBcolV;
    add.u64 %rd4, %rd4, %rdTmp;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rdB;
    ld.global.v4.f32 {%fB4_0, %fB4_1, %fB4_2, %fB4_3}, [%rd4];
    st.shared.v4.f32 [%rd5], {%fB4_0, %fB4_1, %fB4_2, %fB4_3};
BLoad1Done:
SkipBLoad1:
    // Synchronize to ensure all shared loads complete
    bar.sync 0;
    // Inner product over the tile K dimension (k = 0..31)
    // Initialize K loop with pointer arithmetic and unrolling by 4
    // Precompute shared memory base pointers for this thread
    mul.lo.u32 %rTmp32, %rTy, 32;
    cvt.u64.u32 %rdTmp, %rTmp32;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rdArowPtr, %rdAsBase, %rdTmp;      // Asub[ty][0]
    cvt.u64.u32 %rdTmp, %rTx;
    shl.b64 %rdTmp, %rdTmp, 2;
    add.u64 %rdBcolPtr, %rdBsBase, %rdTmp;      // Bsub[0][tx]
    mov.u64 %rdIncA, 4;
    mov.u64 %rdIncB, 64;
    mov.u32 %rK, 0;
KLoop:
    setp.ge.u32 %p1, %rK, 32;
    @%p1 bra KEnd;
    // Unrolled step 0
    ld.shared.f32 %fA2, [%rdArowPtr];
    ld.shared.f32 %fB2, [%rdBcolPtr];
    fma.rn.f32 %fAcc, %fA2, %fB2, %fAcc;
    add.u64 %rdArowPtr, %rdArowPtr, %rdIncA;
    add.u64 %rdBcolPtr, %rdBcolPtr, %rdIncB;
    add.u32 %rK, %rK, 1;
    // Unrolled step 1
    ld.shared.f32 %fA2, [%rdArowPtr];
    ld.shared.f32 %fB2, [%rdBcolPtr];
    fma.rn.f32 %fAcc, %fA2, %fB2, %fAcc;
    add.u64 %rdArowPtr, %rdArowPtr, %rdIncA;
    add.u64 %rdBcolPtr, %rdBcolPtr, %rdIncB;
    add.u32 %rK, %rK, 1;
    // Unrolled step 2
    ld.shared.f32 %fA2, [%rdArowPtr];
    ld.shared.f32 %fB2, [%rdBcolPtr];
    fma.rn.f32 %fAcc, %fA2, %fB2, %fAcc;
    add.u64 %rdArowPtr, %rdArowPtr, %rdIncA;
    add.u64 %rdBcolPtr, %rdBcolPtr, %rdIncB;
    add.u32 %rK, %rK, 1;
    // Unrolled step 3
    ld.shared.f32 %fA2, [%rdArowPtr];
    ld.shared.f32 %fB2, [%rdBcolPtr];
    fma.rn.f32 %fAcc, %fA2, %fB2, %fAcc;
    add.u64 %rdArowPtr, %rdArowPtr, %rdIncA;
    add.u64 %rdBcolPtr, %rdBcolPtr, %rdIncB;
    add.u32 %rK, %rK, 1;
    bra KLoop;
KEnd:
    // Synchronize before loading the next tile
    bar.sync 0;
    add.u32 %rTile, %rTile, 1;
    bra TilesLoop;
TilesEnd:
    // Write result if within bounds
    setp.lt.u32 %pW1, %rRow, %rN;
    setp.lt.u32 %pW2, %rCol, %rN;
    and.pred %pW, %pW1, %pW2;
    @!%pW bra End;
    mul.wide.u32 %rd8, %rRow, %rN;
    cvt.u64.u32 %rdTmp, %rCol;
    add.u64 %rd8, %rd8, %rdTmp;
    shl.b64 %rd8, %rd8, 2;
    add.u64 %rd8, %rd8, %rdC;
    st.global.f32 [%rd8], %fAcc;
End:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_f32_t16x16")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.device.type == "cuda" and B.device.type == "cuda", "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 supported"
        assert A.dim() == 2 and B.dim() == 2 and A.size(0) == A.size(1) and B.size(0) == B.size(1), "Square matrices expected"
        assert A.size(1) == B.size(0), "Incompatible shapes for matmul"
        N = A.size(0)
        C = torch.empty((N, N), device=A.device, dtype=A.dtype)

        block_x, block_y, block_z = 16, 16, 1
        grid_x = (N + block_x - 1) // block_x
        grid_y = (N + block_y - 1) // block_y
        grid_z = 1

        module = _get_ptx_module()
        module.launch(
            "matmul_f32_t16x16",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[A, B, C, u32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

