import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_f32_t16x16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    // Register declarations
    .reg .pred %p0, %p1, %pArow, %pAcol, %pAok, %pAcol2, %pAok2, %pBcol, %pBrow, %pBok, %pBrow2, %pBok2, %pW1, %pW2, %pW;
    .reg .b32 %rTx, %rTy, %rBx, %rBy, %rBdx, %rBdy;
